window.RP_SESSION={"id":"S-c3827f672297","messages":[{"id":"RP-II-0064963","time":"2026-03-17T02:02:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"\"...\"\n\n막상 자러간다고는 했지만,어쩐지 잠이 오지않아 잔불만이 남아있는 화톳불에 앉아 불멍을 때리고있었다.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064964","time":"2026-03-17T02:03:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"저기 저 언덕을 내리쬐는 달빛아래 흐드러지게 핀 꽃밭의 풍경이 일품인지라","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064965","time":"2026-03-17T02:04:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"아직 채 가시지 않은 추위를 무릅쓰고 두터운 옷을 둘러입고 올라본다.\n\n\"썩을.\"","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064966","time":"2026-03-17T02:04:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"\"늙으면...죽어야지...\"","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064967","time":"2026-03-17T02:05:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"언덕을 오르는 동안에 투덜대는 소리가 야심한 숲속에 울렸다. \n\n호- 호- 하는 부엉이 울음소리가 귀뚜라미들의 노랫소리 위에 얹혀졌다.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064968","time":"2026-03-17T02:06:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"언덕을 올라 꽃밭 위에 앉아 굽어보니- 이거 장관이다!","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064969","time":"2026-03-17T02:06:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"은은한 불빛이 켜져있는 길드건물과 저 멀리 떨어진 마을 굴뚝에서 피어오르는 연기가 한 눈에 들어온다.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064970","time":"2026-03-17T02:07:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"\"아-\"\n\n\"이대로 봄바람이나 쐬며 잠이나 청하고싶구만.\"","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064971","time":"2026-03-17T02:08:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"unresolved","type":"dialogue","body":"늙은 척 어이없다!","characters":[]},{"id":"RP-II-0064972","time":"2026-03-17T02:08:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"unresolved","type":"dialogue","body":"인정하면 개추","characters":[]},{"id":"RP-II-0064973","time":"2026-03-17T02:08:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"패잔병은 몸을 이끌고 저기 저 비탈길을 바라보았다.\n\n마차와 노새끄는 수레가 겨우 지나갈법한 길이다.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064974","time":"2026-03-17T02:09:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"\"...\"\n\n\"옛날 생각나네.\"\n\n전쟁 때의 기억이 스멀스멀 올라온다. 그래, 도망자가 되기전의 이야기. \n\n그 이야기를 한번 더 떠올려보기로하였다.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064975","time":"2026-03-17T02:09:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"-","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064976","time":"2026-03-17T02:10:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"종족전쟁 즈음의 레네르트라고한다면 지금의 레네르트와는 조금 다른 인상이라고도 할 수 있겠다.\n\n골기아의 기병 부대중 하나의 나이트 배너릿이었던 시절의 그는 오랜 전쟁 동안 그를 따르는 50정도의 기병대를 이끌고 있었다.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064977","time":"2026-03-17T02:12:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"그때의 상황은 그닥 좋지 않았다. 사생아가 으레 그렇지만, 그는 유독 왕가의 미움을 받아 점점더 위험한 전선으로 향하고 있었으니까","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064978","time":"2026-03-17T02:13:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"레네르트가 주로 맡았던 업무는 물론 중갑기병으로서 적진을 돌파하는 업무도있었지만. 그가 기병대장으로 근무하던 말년즈음에 그가 소속되어있는 부대의 지휘관-그러니까 그의 일가친척은 그를 정찰기병으로서 굴렸다.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064979","time":"2026-03-17T02:15:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"레네르트는 사생아로서 마땅한 영지조차 물려받지못한지라- 그의 이름으로 이끄는 병력따위는 없이 그때 그때 지휘관이 그가 이끌 부대를 지정해주는 식으로 병사를 이끌고 있었다.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064980","time":"2026-03-17T02:17:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"그의 아버지가 살아있었을 적에는 물론 그 역시도 화려한 갑옷의 번쩍이는 중갑 기병대를 이끌었었다.\n\n그러나 그 분이 자리에 없을때는 어떠했겠는가.\n\n그분이 레네르트를 배다른형제가 이끌고 있던 군단으로 보냈을 때에\n\n명목상으로나 기병부대장으로서 이끌고있던 부대의 군마들은 늙고 앙상하기 그지없었고","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064981","time":"2026-03-17T02:17:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"장비는 노후화되어 당시로서는 구식인- 이를테면 과도기적 갑주(Tranditional armor)을 차고 있었다.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064982","time":"2026-03-17T02:19:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"마갑? 늙은 말들에게 그런것을 씌워주었다간 금새 지쳐 쓰러져버릴테지.\n\n그때 그때 임기 응변으로 최전선에서 살아남고있었지만 가문이 내려주는 임무는 날이 갈수록 무모해지고 있었다.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064983","time":"2026-03-17T02:20:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"그 날도 떠맡겨지듯 정찰을 하던 때였다. \n\n레네르트는, 물론 그 자신으로서도 높은곳에서 내려다보는것을 사랑하기도했지만 정찰을 하고자하는 이유로 언덕 위에서 아래를 내려다보고 있었다.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064984","time":"2026-03-17T02:21:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"\"...적들은 벌써 철수했나? 재빠른 귀쟁이놈들.\"\n\n「그러게나 말입니다.」\n\n그와 그의 부관은 쯧 소리를 내며 더럽게 짠 육포나 뜯고있었다.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064985","time":"2026-03-17T02:22:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"\"...이제 곧 다시 이동한다.\"\n\n\"망할-도대체 계속해서 퇴각하는 놈들을 왜 쫓으라는거야?\"","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064986","time":"2026-03-17T02:23:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"「...지휘관님」\n\n\"왜?\"\n\n「아무리봐도 유인하는것같지 않습니까.」\n\n\"...나도 알아.\"","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064987","time":"2026-03-17T02:24:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"「... 이미 놈들의 영토로 너무 깊숙히 들어왔습니다.」\n\n「그리고 이번에는-적어도 놈들이 어디서 주둔했는지는 확인했지 않습니까?」","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064988","time":"2026-03-17T02:25:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"「...사령관님도 이해해 주실겁니다.」\n\n「이만 퇴각합시다.」\n\n\"...벨른도르프.\"","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064989","time":"2026-03-17T02:26:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"\"임무는 놈들의 '주둔지'를 찾는거였어.\"\n\n\"주둔지 '터'가 아니지.\"\n\n「불가능하단걸 아시잖습니까.」\n\n\"알아.\"","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064990","time":"2026-03-17T02:27:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"\"그러나 이대로 돌아가면,보나마나 임무를 실패했다는 이유로 그분께서 또 나를 몰아세우시지 않겠나.\"\n\n\"...그러니 무슨 수라도 있나.\"","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064991","time":"2026-03-17T02:27:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"\"어떻게 해서든, 그 망할 귀쟁이의 얼굴이라도 보고가야지.\"\n\n「...예.」\n\n\"출발한다!\"","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064992","time":"2026-03-17T02:29:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"그렇게 기병대가 숲을 지나던 와중이었다.\n\n울창한 숲속- 온갖 새들의 울음소리가 이곳저곳 들려오며 들짐승들이 풀을 헤집어 놓는 소리가 신경을 건드렸다.\n\n그리고 그때.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064993","time":"2026-03-17T02:29:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"쐐액-\n메시지가 삭제되었습니다.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064994","time":"2026-03-17T02:29:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064995","time":"2026-03-17T02:29:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레네르트'의 민첩 판정 :\n[10] + [0] = [10]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-II-0064996","time":"2026-03-17T02:30:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"\"...!\"\n\n재빠르게 말머리를 돌린덕분에-간신히 피하였다.\n\n레네르트의 머리 높이로 박힌 화살-그것이 의미하는것은...","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064997","time":"2026-03-17T02:30:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"\"기습이다-!'\n\n\"전원 빠르게 숲을 돌파한다!\"","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064998","time":"2026-03-17T02:32:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"그 순간, 풀숲사이로 수많은 적 보병들이 기병부대를 막아서기 시작했다.\n\n파이크보다는 조금 짧은,그러나 적을 찌르기는 충분한- 기나긴 창. 그것들로 그들은 말의 움직임을 막으려들었다","characters":["P-ec13f36acacc"]},{"id":"RP-II-0064999","time":"2026-03-17T02:32:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"\"망할-!\"\n\n다른 수가없었다.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0065000","time":"2026-03-17T02:32:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"!힘 +2","characters":["P-ec13f36acacc"]},{"id":"RP-II-0065001","time":"2026-03-17T02:32:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레네르트'의 힘 판정 :\n[10] + [2] + [2] = [14]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-II-0065002","time":"2026-03-17T02:33:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"그대로 그들이 제대로 진을 갖추기전,빠르게 그들에게 달려들어 그들을 뭉개버렸다.\n\n당시에 레네르트는 엘프의 언어를 알아들을수 없었지만- 모든 종족의 비명소리는 그 어떤 종족이던 다르지않았다.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0065003","time":"2026-03-17T02:35:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"말이 그를 막아서려던 적의 안면을 물어뜯고,앞발로 뭉개트린다.\n\n\"어서 나를따르라!\"\n\n적의 어깨에 검을 내려찍는다. 보병의 쇄자갑의 파편이 쇳소리를 내며 터져나왔다","characters":["P-ec13f36acacc"]},{"id":"RP-II-0065004","time":"2026-03-17T02:36:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"뒤로 쏘아지는 화살소리.곧곧에서 터져나오는 비명소리.\n\n그렇게 한참을 달리고나서야 기병부대는 간신히 빠져나올수 있었고...","characters":["P-ec13f36acacc"]},{"id":"RP-II-0065005","time":"2026-03-17T02:36:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"!d50","characters":["P-ec13f36acacc"]},{"id":"RP-II-0065006","time":"2026-03-17T02:36:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"결과 : [1]\n합계 : [1]","characters":[]},{"id":"RP-II-0065007","time":"2026-03-17T02:36:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"\"...\"\n\n레네르트는 완전히 홀로 남아버렸다.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0065008","time":"2026-03-17T02:37:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"젠장, 다들 어디로가버린거야? 분명히 다들 따라오라고...!\n\n저 멀리에서 바라보니.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0065009","time":"2026-03-17T02:37:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"...레네르트를 따르던 기사들은 스무명 남짓만이 남은채로 저기 저 평야를 향해 도망치고있었다.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0065010","time":"2026-03-17T02:38:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"분명,제 지휘관을 잃어버리자 그가 죽었다고 판단.\n\n독단적으로 도망쳐나온것이겠지.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0065011","time":"2026-03-17T02:39:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"그렇게 레네르트는 50에 달하는 기병부대를 궤멸시킨 셈이 되어버렸다.\n\n이대로 돌아가보았자 무슨 취급을 당하겠는가?","characters":["P-ec13f36acacc"]},{"id":"RP-II-0065012","time":"2026-03-17T02:39:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"...패잔병.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0065013","time":"2026-03-17T02:39:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"그 이상, 그 이하도아니었다.\n\n\"...그래요, 형님.\"","characters":["P-ec13f36acacc"]},{"id":"RP-II-0065014","time":"2026-03-17T02:40:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"\"당신의 계획대로 되었군요.\"","characters":["P-ec13f36acacc"]},{"id":"RP-II-0065015","time":"2026-03-17T02:41:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"레네르트는 조용히 말을 몰아- 방랑길에 올랐다.\n\n어디로 향하는것인지도 모른채로-한참을. 잠시동안은 패전후 도망친 장수를 찾는다는 현상금 수배서가 보이곤했지만 \n\n장기간 보이지 않자 나라는 그가 죽었다고 판단- 수배를 거두었다.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0065016","time":"2026-03-17T02:41:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"-","characters":["P-ec13f36acacc"]},{"id":"RP-II-0065017","time":"2026-03-17T02:42:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"\"...\"\n\n레네르트는 비탈길을 바라보며 중얼거렸다.\n\n\"...그놈들은 제대로 살아돌아는 갔을련지.'","characters":["P-ec13f36acacc"]},{"id":"RP-II-0065018","time":"2026-03-17T02:43:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"어쩌면 마적단이되었을수도있고,엘프들에게 추적당해 죽었을수도있다.\n\n애초에 버려질 목적으로 만들어진 부대의 패잔병들의 운명은 불보듯 뻔하다.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0065019","time":"2026-03-17T02:44:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"그러나  살아있기를 바라는 것이 사람의 마음인지라.\n\n패잔병은 조용히 언덕을 굽어살피며 중얼거렸다.","characters":["P-ec13f36acacc"]},{"id":"RP-II-0065020","time":"2026-03-17T02:45:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"\"그날로 이미 기사 레네르트는 죽은게 아니었을련지.\"","characters":["P-ec13f36acacc"]},{"id":"RP-II-0065021","time":"2026-03-17T02:45:00+09:00","room":"RP II","name":"레네르트 / 벨른도르프와 과거 기병대","profile":"레네르트","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-ec13f36acacc"]},{"id":"RP-II-0065022","time":"2026-03-17T02:45:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
